    public static function svg(string $name, int $size = 14, array $attrs = []): string {
        $key = strtolower(trim($name));
        $content = self::$icons[$key] ?? self::$icons['hash'];

        $strokeWidth = $attrs['stroke-width'] ?? '2';
        $class = $attrs['class'] ?? 'zrx-icon';
        $color = $attrs['color'] ?? 'currentColor';

        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="%s" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            htmlspecialchars($class),
            $size,
            $size,
            htmlspecialchars($color),
            htmlspecialchars((string)$strokeWidth),
            $content
        );
    }
    public static function getAll(): array {
        return self::$icons;
    }
}

function zrx_icon(string $name, int $size = 14, array $attrs = []): string {
    return ZimRxIcon::svg($name, $size, $attrs);
}
